func _is_inside(point: Vector2, poly: PackedVector2Array) -> bool:
	# Returns whether point is inside the given polygon.
	return Geometry2D.is_point_in_polygon(point, poly)


func _is_walkable(point: Vector2, boundary: PackedVector2Array, holes: Array) -> bool:
	# Returns whether a point is inside the boundary but not in any hole.
	# Use a tiny epsilon for point-in-polygon to handle boundary cases gracefully.
	var epsilon: float = 1e-4
	# For point-in-polygon edge/hole cases, use a small offset if needed; however,
	# Geometry2D.is_point_in_polygon is point-wise. A robust approach for triangle-
	# centroid queries: point on edge is tricky. Rely on centroid containment.
	if not Geometry2D.is_point_in_polygon(point, boundary):
		return false
	for hole in holes:
		if Geometry2D.is_point_in_polygon(point, hole):
			return false
	return true


func build(boundary: PackedVector2Array, holes: Array) -> void:
	"""
	Builds the navigation mesh by triangulating the walkable region: boundary minus holes.
	"""
	# Geometry2D.triangulate_delaunay operates on points; it doesn't handle
	# holes directly. Instead, build a contour using the outer boundary
	# and the inner holes. The standard trick: connect holes to the boundary
	# with zero-width "bridges" to create a single non-self-intersecting
	# polygon representing the entire walkable area. Then triangulate.
	#
	# Alternatively, a more robust approach in Godot: create a polygon with
	# holes using Geometry2D.clip_polygons, then triangulate the result. This is
	# cleaner. Geometry2D.clip_polygons(boundary, hole) = boundary \ hole.
	# Successively clip: region = boundary; for hole in holes: region = clip(region, hole).
	# The result can be multiple polygons. Then triangulate each.
	var region: Array = [boundary]
	for hole in holes:
		var new_region: Array = []
		for poly in region:
			var result: Array = Geometry2D.clip_polygons(poly, hole)
			for p in result:
				new_region.push_back(p)
		region = new_region

	# Now triangulate each polygon piece.
	triangles = []
	for poly in region:
		var poly_tris: PackedInt32Array = Geometry2D.triangulate_delaunay(poly)
		# triangulate_delaunay returns a flat array of vertex indices (i0, i1, i2).
		for i in range(0, poly_tris.size(), 3):
			var t: PackedVector2Array = [
				poly[poly_tris[i]],
				poly[poly_tris[i + 1]],
				poly[poly_tris[i + 2]]
			]
			# Drop degenerate triangles (area ~0).
		if abs(Geometry2D.triangulation_area(t)) < 1e-4:
