		var c: Vector2 = (t[0] + t[1] + t[2]) / 3.0
		centroids.push_back(c)
		graph.add_point(i, c)

	# Connect adjacent triangles.
	# Two triangles are adjacent if they share a common edge (two vertices at the same position).
	for i in range(n):
