# A 2D navigation mesh generator that triangulates a walkable region
# defined by an outer boundary polygon with zero or more holes, builds
# a triangle adjacency graph, and provides spatial and pathfinding queries.

var triangles: Array = []  # Array of PackedVector2Array
var adj: Array = []        # Array of Array of int (adjacency list)
var graph: AStar2D = null  # Adjacency graph keyed by triangle centroid index


func build(boundary: PackedVector2Array, holes: Array) -> void:
	"""
	Builds the navigation mesh by triangulating the walkable region: boundary minus holes.
	"""
	var region: Array = [boundary]
	for hole in holes:
		var new_region: Array = []
		for poly in region:
			var result: Array = Geometry2D.clip_polygons(poly, hole)
			for p in result:
				new_region.push_back(p)
		region = new_region

	# Now triangulate each polygon piece.
	triangles = []
	for poly in region:
		var poly_tris: PackedInt32Array = Geometry2D.triangulate_delaunay(poly)
		# triangulate_delaunay returns a flat array of vertex indices (i0, i1, i2).
		for i in range(0, poly_tris.size(), 3):
			var t: PackedVector2Array = [
				poly[poly_tris[i]],
				poly[poly_tris[i + 1]],
				poly[poly_tris[i + 2]]
			]
			# Drop degenerate triangles (area ~0).
			if abs(_tri_area(t)) < 1e-4:
				continue
			triangles.push_back(t)

	# Build adjacency and the AStar2D graph.
	_rebuild_graph(boundary, holes)


func _tri_area(t: PackedVector2Array) -> float:
	# Area of a triangle: 0.5 * cross product
	return 0.5 * (t[0].x * (t[1].y - t[2].y) + t[1].x * (t[2].y - t[0].y) + t[2].x * (t[0].y - t[1].y))


func _rebuild_graph(_boundary: PackedVector2Array, _holes: Array) -> void:
