extends SceneTree

func _init():
	var boundary = PackedVector2Array([Vector2(0,0), Vector2(100,0), Vector2(100,100), Vector2(0,100)])
	var hole = PackedVector2Array([Vector2(25,25), Vector2(75,25), Vector2(75,75), Vector2(25,75)])
	# Bridge: connect boundary to hole. Find closest points.
	# Boundary has 4, hole has 4. Pick closest vertex to closest vertex.
	var min_dist = 1e10
	var bi = -1, hi = -1
	for i in range(boundary.size()):
		for j in range(hole.size()):
			var d = boundary[i].distance_to(hole[j])
			if d < min_dist:
				min_dist = d
				bi = i
				hi = j
	print("bi: ", bi, ", hi: ", hi)

	# Construct contour: B0..Bi, H_hi..Hj..H_hi, Bi..Bn-1, B0
	var contour = PackedVector2Array()
	for i in range(bi + 1):
		contour.push_back(boundary[i])
	for j in range(hole.size()):
		contour.push_back(hole[(hi + j) % hole.size()])
	contour.push_back(hole[hi])
	contour.push_back(boundary[bi])
	for i in range(bi + 1, boundary.size()):
		contour.push_back(boundary[i])
	contour.push_back(boundary[0])
	print("contour size: ", contour.size())

	var tris = Geometry2D.triangulate_delaunay(contour)
	print("tris count: ", tris.size()/3)
	quit()
