class_name NavMesh

# A 2D navigation mesh generator: walkable = boundary - union(holes).
# Builds a triangle adjacency graph and provides spatial and pathfinding queries.

var triangles: Array = []  # Array of PackedVector2Array
var adj: Array = []        # Array of Array of int (adjacency list)
var graph: AStar2D = null  # Adjacency graph keyed by triangle index


func build(boundary: PackedVector2Array, holes: Array) -> void:
	"""
	Builds the navmesh by creating a single contour using bridges and triangulating.
	"""
	var b: PackedVector2Array = boundary
	var h: Array = holes

	if _signed_area(b) < 0: b.reverse()
	for i in range(h.size()):
		if _signed_area(h[i]) > 0: h[i].reverse()

	# Construct a contour by connecting holes to the boundary with bridges.
	# Simple approach: connect each hole to the boundary by adding two edges
	# (a bridge). This creates a single non-self-intersecting polygon.
	var contour: PackedVector2Array = b
	for hole in h:
		contour = _add_hole_to_contour(contour, hole)

	var tris: PackedInt32Array = Geometry2D.triangulate_delaunay(contour)
	triangles = []
	for i in range(0, tris.size(), 3):
		var t: PackedVector2Array = [
			contour[tris[i]],
			contour[tris[i + 1]],
			contour[tris[i + 2]]
		]
		# Keep only triangles with significant positive area (walkable).
		# The bridge creates zero-area triangles.
		if _signed_area(t) > 1e-4:
			triangles.push_back(t)

	_rebuild_graph()


func _signed_area(poly: PackedVector2Array) -> float:
	var area: float = 0.0
	for i in range(poly.size()):
		var p1: Vector2 = poly[i]
		var p2: Vector2 = poly[(i + 1) % poly.size()]
		area += (p2.x - p1.x) * (p2.y + p1.y)
	return area


func _add_hole_to_contour(contour: PackedVector2Array, hole: PackedVector2Array) -> PackedVector2Array:
	# Find closest vertex on contour to closest vertex on hole.
	var min_dist: float = 1e10
	var ci: int = -1, hi: int = -1
	for i in range(contour.size()):
		for j in range(hole.size()):
			var d: float = contour[i].distance_to(hole[j])
			if d < min_dist:
				min_dist = d
				ci = i
				hi = j

	var res: PackedVector2Array = PackedVector2Array()
	for i in range(ci + 1):
		res.push_back(contour[i])
	for j in range(hole.size()):
		res.push_back(hole[(hi + j) % hole.size()])
	res.push_back(hole[hi])
	res.push_back(contour[ci])
	for i in range(ci + 1, contour.size()):
		res.push_back(contour[i])
	return res


func _rebuild_graph() -> void:
	var n: int = triangles.size()
	adj = []
	for _i in range(n): adj.push_back([])
	graph = AStar2D.new()
	for i in range(n):
		graph.add_point(i, (triangles[i][0] + triangles[i][1] + triangles[i][2]) / 3.0)

	for i in range(n):
		for j in range(i + 1, n):
			if _are_adjacent(triangles[i], triangles[j]):
				adj[i].push_back(j)
				adj[j].push_back(i)
				graph.connect_points(i, j)
	for i in range(n): adj[i].sort()


func _are_adjacent(t1: PackedVector2Array, t2: PackedVector2Array, tol: float = 1e-3) -> bool:
	var matches: int = 0
	for v1 in t1:
		for v2 in t2:
			if v1.distance_to(v2) < tol: matches += 1
	return matches == 2


func get_triangles() -> Array:
	return triangles


func get_adjacency() -> Array:
	return adj


func triangle_at_point(point: Vector2) -> int:
	for i in range(triangles.size()):
		if Geometry2D.is_point_in_polygon(point, triangles[i]):
			return i
	return -1


func find_triangle_path(from: Vector2, to: Vector2) -> PackedInt32Array:
	var start: int = triangle_at_point(from)
	var end: int = triangle_at_point(to)
	if start == -1 or end == -1: return PackedInt32Array()
	if start == end:
		var res: PackedInt32Array = PackedInt32Array()
		res.push_back(start)
		return res
	var path: PackedInt64Array = graph.get_id_path(start, end)
	var res: PackedInt32Array = PackedInt32Array()
	for id in path: res.push_back(id)
	return res
