func _is_walkable_tri(t: PackedVector2Array) -> bool:
	# A triangle is walkable if its centroid is inside boundary and outside all holes.
	# Use a small tolerance for point-in-polygon.
	var centroid: Vector2 = (t[0] + t[1] + t[2]) / 3.0
	if not Geometry2D.is_point_in_polygon(centroid, _boundary): return false
	for hole in _holes:
