	for i in range(ci + 1): res.push_back(contour[i])
	for j in range(hole.size()): res.push_back(hole[(hi + j) % hole.size()])
	res.push_back(hole[hi])
	res.push_back(contour[ci])
	for i in range(ci + 1, contour.size()): res.push_back(contour[i])
	return res


func _rebuild_graph() -> void:
	var n: int = triangles.size()
	adj = []
	for _i in range(n): adj.push_back([])
	graph = AStar2D.new()
	for i in range(n):
