class_name NavMesh

# A 2D navigation mesh generator that triangulates the walkable region
# defined by an outer boundary with zero or more holes, builds a triangle
# adjacency graph, and provides spatial and pathfinding queries.

var triangles: Array = []  # Array of PackedVector2Array
var adj: Array = []        # Array of Array of int
var graph: AStar2D = null  # Adjacency graph keyed by triangle index


func build(boundary: PackedVector2Array, holes: Array) -> void:
	"""
	Builds the navmesh by decomposing the boundary into convex pieces, then
	clipping each hole from those pieces, and triangulating the result.
	"""
	var pieces: Array = Geometry2D.decompose_polygon_in_convex(boundary)

	var walkable_polys: Array = []
	for p in pieces:
		var current: Array = [p]
		for hole in holes:
			var next: Array = []
			for cp in current:
				var res: Array = Geometry2D.clip_polygons(cp, hole)
				for r in res: next.push_back(r)
			current = next
		for cp in current:
			walkable_polys.push_back(cp)

	triangles = []
	for poly in walkable_polys:
		var poly_tris: PackedInt32Array = Geometry2D.triangulate_delaunay(poly)
		for i in range(0, poly_tris.size(), 3):
			var t: PackedVector2Array = [
				poly[poly_tris[i]],
				poly[poly_tris[i + 1]],
				poly[poly_tris[i + 2]]
			]
			if abs(_signed_area(t)) > 1e-4:
				triangles.push_back(t)

	_rebuild_graph()


func _signed_area(t: PackedVector2Array) -> float:
	return 0.5 * (t[0].x * (t[1].y - t[2].y) + t[1].x * (t[2].y - t[0].y) + t[2].x * (t[0].y - t[1].y))


func _rebuild_graph() -> void:
	var n: int = triangles.size()
	adj = []
	for _i in range(n): adj.push_back([])
	graph = AStar2D.new()
	for i in range(n):
		graph.add_point(i, (triangles[i][0] + triangles[i][1] + triangles[i][2]) / 3.0)

	for i in range(n):
		for j in range(i + 1, n):
			if _are_adjacent(triangles[i], triangles[j]):
				adj[i].push_back(j)
				adj[j].push_back(i)
				graph.connect_points(i, j)
	for i in range(n): adj[i].sort()


func _are_adjacent(t1: PackedVector2Array, t2: PackedVector2Array, tol: float = 1e-3) -> bool:
	var matches: int = 0
	for v1 in t1:
		for v2 in t2:
			if v1.distance_to(v2) < tol: matches += 1
	return matches == 2


func get_triangles() -> Array: return triangles
func get_adjacency() -> Array: return adj


func triangle_at_point(point: Vector2) -> int:
	for i in range(triangles.size()):
		if Geometry2D.is_point_in_polygon(point, triangles[i]): return i
	return -1


func find_triangle_path(from: Vector2, to: Vector2) -> PackedInt32Array:
	var start: int = triangle_at_point(from)
	var end: int = triangle_at_point(to)
	if start == -1 or end == -1: return PackedInt32Array()
	if start == end:
		var res: PackedInt32Array = PackedInt32Array()
		res.push_back(start)
		return res
	var path: PackedInt64Array = graph.get_id_path(start, end)
	var res: PackedInt32Array = PackedInt32Array()
	for id in path: res.push_back(id)
	return res
